// Runtime loader for the build-time RePoE metadata-id -> name map
// (backend/v2/networth/base-names.json, generated by
// backend/v2/base-names-gen.mjs). Bridges Faustus's Metadata-ID-keyed
// ratios to our name-based descriptors (see kinds.mjs/valuator.mjs).
import { readFile } from 'node:fs/promises'

const BASE_NAMES_JSON = new URL('./base-names.json', import.meta.url)

/**
 * Loads base-names.json and builds { byId }.
 * - byId: Map<metadataId, name> — 1:1, straight from the JSON. This is the only
 *   direction anyone consumes: faustus.mjs keys the GGG ratios by metadata id
 *   and maps them to descriptor names via byId. (A reverse name->id map was
 *   dropped as dead code — nothing but its own test read it.)
 */
export async function loadBaseNames (path = BASE_NAMES_JSON) {
  const raw = await readFile(path, 'utf8')
  const data = JSON.parse(raw)
  return { byId: new Map(Object.entries(data)) }
}
